R1_classify_alert.text:
{
  "title": "硫化溫度異常",
  "summary": "CURE-07溫度驟降至122°C，已硫化10h/28h，需檢視蒸汽管線H2與活化能歸因。"
}

R2_plan.text:
{
  "goal": "判斷是單機故障或蒸汽主管路問題，並決定是延長硫化時間還是重排",
  "hypothesis": {
    "id": "temp_drop_7",
    "statement": "溫度下降是由單一機台蒸汽洩漏或感測器漂移引起，非主管路問題",
    "cause_code": "single_leak_or_sensor_drift",
    "expectation": {
      "machine_id": "CURE-07",
      "channel": "temp_c",
      "op": "between",
      "value": 121.0,
      "value_hi": 123.0,
      "within_min": 30
    }
  },
  "steps": [
    {
      "id": "S1",
      "tool": "read_sensors",
      "args": {"machine_id": "CURE-07"},
      "purpose": "取得最新溫度與蒸汽壓數值"
    },
    {
      "id": "S2",
      "tool": "predict_anomaly",
      "args": {"machine_id": "CURE-07", "channel": "temp_c"},
      "purpose": "判斷是否符合感測器漂移或單機洩漏模式"
    },
    {
      "id": "S3",
      "tool": "cure_formula",
      "args": {
        "initial_temp": 128.0,
        "current_temp": 122.0,
        "initial_time": 10,
        "total_time": 28,
        "activation_energy": 85.0
      },
      "purpose": "依等效硫化公式重算剩餘所需時間"
    },
    {
      "id": "S4",
      "tool": "solve_schedule",
      "args": {"recalc": true},
      "purpose": "依新硫化時間重新排程，檢查人力缺口"
    }
  ],
  "alert_card": {
    "title": "CURE-07 溫度下降處置",
    "summary": "溫度從 128°C 下降至 122°C，需判斷是單機問題還是蒸汽主管路問題，並決定是延長硫化時間還是重新排程。依 SOP-CP-02 處理。"
  }
}

R3_replan.text:
